trailRoutes.post(
  "/:host/:owner/:repo",
  describeRoute({
    tags: ["Trails"],
    summary: "Create a new trail",
    requestBody: {
      required: true,
      content: {
        "application/json": {
          schema: createTrailBodySchema,
        },
      },
    },
    responses: {
      201: {
        description: "Trail created",
        content: {
          "application/json": {
            schema: resolver(
              z.object({
                trail: trailInfoSchema,
                branch_created: z.boolean(),
                has_write_permission: z.boolean(),
              }),
            ),
          },
        },
      },
      400: {
        description: "Validation error",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
      401: {
        description: "Not authenticated",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
      409: {
        description: "A trail already exists for the requested branch",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
    },
  }),
  async (c) => {
    const ctx = await resolveUserContext(c)
    if (ctx instanceof Response) return ctx
    const { db, repo: repoAccess, repoFullName, user } = ctx

    try {
      const appCreds = { appId: c.env.GITHUB_CLIENT_ID, privateKey: c.env.GITHUB_APP_PRIVATE_KEY }

      // Check installation permissions — if no installation, we can still create a trail without a branch
      let hasWritePermission = false
      let githubInstallationId: number | null = null
      if (repoAccess.installation_id) {
        githubInstallationId = await db.installations.getGithubId(repoAccess.installation_id)
        if (githubInstallationId) {
          hasWritePermission = await checkInstallationWritePermission(
            githubInstallationId,
            appCreds,
            c.env.ENTIRE_CACHE,
          )
        }
      }

      const body = await c.req.json<{
        title: string
        body?: string
        branch_name?: string
        base?: string
        status?: TrailStatus
        assignees?: string[]
        labels?: string[]
        priority?: TrailPriority
      }>()

      if (!body.title?.trim()) {
        return c.json({ error: "Title is required" }, 400)
      }
      if (body.branch_name) {
        if (!isValidBranchName(body.branch_name)) {
          return c.json({ error: "Invalid branch name format" }, 400)
        }
        if (body.branch_name.startsWith("entire/")) {
          return c.json({ error: "Cannot create branches under 'entire/' namespace" }, 400)
        }
      }
      if (body.status !== undefined && !VALID_TRAIL_STATUSES.includes(body.status as TrailStatus)) {
        return c.json(
          { error: `Invalid status. Must be one of: ${VALID_TRAIL_STATUSES.join(", ")}` },
          400,
        )
      }
      if (body.priority !== undefined && !VALID_PRIORITIES.includes(body.priority)) {
        return c.json(
          { error: `Invalid priority. Must be one of: ${VALID_PRIORITIES.join(", ")}` },
          400,
        )
      }
      const base = body.base || repoAccess.default_branch || "main"
      const now = new Date().toISOString()

      let branchCreated = false
      let branchLinked = false
      let installationToken: string | null = null

      if (body.branch_name && hasWritePermission && githubInstallationId) {
        installationToken = await getInstallationToken(
          githubInstallationId,
          appCreds,
          c.env.ENTIRE_CACHE,
        )
        branchCreated = await createBranchIfNotExists(
          repoFullName,
          body.branch_name,
          base,
          installationToken,
        )
        branchLinked = true
      }

      const status = body.status ?? "open"

      const { row: persistedTrail, created } = await db.trails.create({
        repo_id: repoAccess.id,
        branch: branchLinked ? body.branch_name || null : null,
        original_branch: branchLinked ? body.branch_name || null : null,
        base,
        title: body.title.trim(),
        status,
        author_user_id: user.id,
        assignees: body.assignees || [],
        labels: body.labels || [],
        priority: body.priority ?? "none",
        created_at: now,
        updated_at: now,
      })

      // A trail with this branch already exists: db.trails.create returns the
      // existing row (created: false) rather than inserting. On the interactive
      // create path that's a naming collision — surface it instead of silently
      // handing back a different trail as if creation succeeded.
      if (!created) {
        return c.json({ error: `A trail already exists for branch "${body.branch_name}"` }, 409)
      }
      // Seed the body editor document (the source of truth) from the request
      // body — there is no longer a `body` column to write to.
      const bodyDocument = await ensureTrailBodyDocument(
        db,
        persistedTrail,
        user.id,
        body.body?.trim() || null,
      )

      if (installationToken && repoAccess.default_branch) {
        try {
          await linkExistingPR(
            db,
            repoFullName,
            repoAccess.id,
            persistedTrail,
            repoAccess.default_branch,
            installationToken,
          )
        } catch (err) {
          console.error(`Failed to link existing PR for new trail #${persistedTrail.number}:`, err)
        }
      }

      const trailInfo: TrailInfo = {
        id: persistedTrail.id,
        number: persistedTrail.number,
        branch: getTrailHistoryBranch(persistedTrail),
        base: persistedTrail.base,
        title: persistedTrail.title,
        body_document: bodyDocument,
        status: persistedTrail.status,
        phase: deriveTrailPhase(persistedTrail.status, {
          hasCodeChanges: persistedTrail.has_code_changes,
        }),
        author: persistedTrail.author,
        assignees: persistedTrail.assignees,
        labels: persistedTrail.labels,
        created_at: persistedTrail.created_at,
        updated_at: persistedTrail.updated_at,
        merged_at: persistedTrail.merged_at,
        priority: (persistedTrail.priority ?? "none") as TrailPriority,
        reviewers: Array.isArray(persistedTrail.reviewers)
          ? (persistedTrail.reviewers as unknown as TrailReviewer[])
          : [],
        requested_reviewers: persistedTrail.requested_reviewers ?? [],
        comment_count: persistedTrail.comment_count,
        unresolved_count: persistedTrail.unresolved_count,
        checkpoint_count: 0,
      }

      return c.json(
        {
          trail: trailInfo,
          branch_created: branchCreated,
          has_write_permission: hasWritePermission,
        },
        201,
      )
    } catch (err) {
      if (isGitHubAuthError(err)) {
        return c.json({ error: "GitHub token expired" }, 401)
      }
      console.error(`Failed to create trail for ${repoFullName}:`, err)
      recordSpanError(err)
      return c.json({ error: "Failed to create trail" }, 500)
    }
  },
)

